/// <summary>
/// Which standard D365FO data entities the bulk SKU/barcode sync exports from.
///
/// A single row, environment-wide - see SaveDataPerCompany below, same reasoning as
/// HSMobileOpsLicenseSetup: which entities carry item and barcode master data is a property of
/// this AOS deployment, not of any one legal entity.
///
/// **Both fields are configurable rather than compiled in, on purpose.** `HSMobileOpsSkuExportSetup`
/// ships with best-known defaults for a standard, unmodified D365FO environment
/// (`EcoResReleasedProductV2Entity` for items, `InventItemBarcodeEntity` for barcodes) - the AOT
/// names behind the public `ReleasedProductsV2`/barcode entities - but neither name has been
/// confirmed against a live environment the way every other DMF entity name in this app has (see
/// HSMobileOpsCountingExportSetup's own class doc for what that confirmation process looks like).
/// An environment where these differ - a different version, a customization, a renamed entity -
/// can be pointed at the right one here without an AOS code change or redeployment. A blank field
/// means "use the built-in default" - see HSMobileOpsSkuExportSetup::itemEntityAotName/
/// barcodeEntityAotName.
/// </summary>
public class HSMobileOpsSkuSyncSetup extends common
{
}

Method.Source:
/// <summary>
/// The one setup row, or an unsaved empty one before anyone has configured anything - mirrors
/// HSMobileOpsLicenseSetup::find. An empty row is a perfectly good answer here: every accessor
/// on this table already treats a blank field as "use the default."
/// </summary>
public static HSMobileOpsSkuSyncSetup find(boolean _forUpdate = false)
{
    HSMobileOpsSkuSyncSetup setup;

    setup.selectForUpdate(_forUpdate);

    select firstOnly setup;

    return setup;
}

/// <summary>
/// Read-only display of what HSMobileOpsSkuExportSetup::itemEntityAotName() will actually use
/// - the configured override if one is set, otherwise the compiled-in default. Shown on the
/// setup form so "what will this actually export against" never requires reading X++ to answer.
/// </summary>
display str effectiveItemEntityName()
{
    return this.ItemEntityName ? this.ItemEntityName : HSMobileOpsSkuExportSetup::defaultItemEntityAotName();
}

/// <summary>
/// See effectiveItemEntityName - the same idea for the barcode entity.
/// </summary>
display str effectiveBarcodeEntityName()
{
    return this.BarcodeEntityName ? this.BarcodeEntityName : HSMobileOpsSkuExportSetup::defaultBarcodeEntityAotName();
}
